UPDATE testimonials SET client_name = 'Дмитрий П.', city = 'Новосибирск', text = 'После консультации получили чёткий план действий и понимание, как помочь сыну с СДВГ. Занятия дают результат - ребёнок стал спокойнее, может концентрироваться на задачах. Спасибо за профессионализм!', rating = 5 WHERE id = 5;
UPDATE testimonials SET client_name = 'Наталья В.', city = 'Краснодар', text = 'Работаем уже год. Дочке поставили задержку психического развития в 4 года. Сейчас ей 5, и она догнала сверстников по многим показателям! Невероятно благодарна за индивидуальный подход и веру в моего ребёнка.', rating = 5 WHERE id = 6;
UPDATE testimonials SET client_name = 'Светлана Л.', city = 'Владивосток', text = 'Приезжала специалист в наш город на 3 недели. За это время провели диагностику и 10 занятий. Получили огромный толчок в развитии! Сын стал более внимательным, речь улучшилась. Ждём следующего приезда!', rating = 5 WHERE id = 7;
UPDATE testimonials SET client_name = 'Александра Т.', city = 'Иркутск', text = 'После первой консультации сразу стало понятно, в каком направлении двигаться. Специалист объяснила всё доступно, дала конкретные упражнения для дома. Планируем продолжать занятия курсом.', rating = 5 WHERE id = 8;